const Api = () => {
  useEffect(() => {
  fetch("https://jsonplaceholder.typicode.com/posts")
  .then((result) => result.json())
  .then(resp => console.log('Result', resp));
  }, []);

  return (
  <div>
    <h1>API Data</h1>
  </div>
  )
}
export default Api;
